import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"快速上手指南","description":"MetaFusion 平台使用、资源探索、播放预览与社区共建入门。","frontmatter":{"title":"快速上手指南","description":"MetaFusion 平台使用、资源探索、播放预览与社区共建入门。","order":2,"group":"start"},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md"}'),l={name:"quickstart.md"};function e(n,t,s,d,h,c){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="快速上手指南" tabindex="-1">快速上手指南 <a class="header-anchor" href="#快速上手指南" aria-label="Permalink to &quot;快速上手指南&quot;">​</a></h1><p>欢迎使用 MetaFusion！本指南将帮助你在 5 分钟内了解如何探索资源、播放多媒体内容以及参与社区共建。</p><hr><h2 id="_1-注册与登录" tabindex="-1">1. 注册与登录 <a class="header-anchor" href="#_1-注册与登录" aria-label="Permalink to &quot;1. 注册与登录&quot;">​</a></h2><ol><li>打开网站登录页面，点击 <strong>“加入 MetaFusion”</strong> 切换至注册表单。</li><li>输入用户名、邮箱与密码。若平台当前处于邀请制阶段，请输入收到的邀请码。</li><li>注册并登录成功后，即可解锁全部功能： <ul><li>无限制查看与播放全量媒体资源；</li><li>创建与编辑词条，参与元数据共建；</li><li>在社区板块发帖、回帖与私信交流；</li><li>在个人设置中生成用于程序化调用的 <strong>PAT 个人访问令牌</strong>。</li></ul></li></ol><hr><h2 id="_2-探索与多维检索" tabindex="-1">2. 探索与多维检索 <a class="header-anchor" href="#_2-探索与多维检索" aria-label="Permalink to &quot;2. 探索与多维检索&quot;">​</a></h2><p>MetaFusion 提供了直观且强大的检索系统：</p><ul><li><strong>全局极速搜索</strong>：在首页或导航栏输入关键词，支持按作品名、罗马音、创作者、别名或标签进行即时联想。</li><li><strong>分类导航</strong>：在探索页按音乐、动画、游戏、影视、文学等大类浏览精选内容。</li><li><strong>动态标签过滤</strong>：结合多个标签（如 <code>原声集</code> + <code>无损音质</code> + <code>2020年代</code>）进行交集精准定位。</li><li><strong>创作者关系图谱</strong>：点击任意艺术家详情，即可查看其参与的所有作词、作曲、配音与制作作品关系网。</li></ul><hr><h2 id="_3-资源播放与多媒体体验" tabindex="-1">3. 资源播放与多媒体体验 <a class="header-anchor" href="#_3-资源播放与多媒体体验" aria-label="Permalink to &quot;3. 资源播放与多媒体体验&quot;">​</a></h2><ul><li><strong>常驻音频播放器</strong>：点击任意音乐曲目，页面底栏将展开全功能播放器，支持连续播放、波形预览、歌词同步滚动与列表管理。</li><li><strong>流媒体切片预览</strong>：音视频资源支持极速加载的 HLS 流与画质自适应切换。</li><li><strong>资源安全下载</strong>：登录用户在作品详情页点击下载时，系统将生成专属安全下载链接。</li></ul><hr><h2 id="_4-个性化首页与频道自定义" tabindex="-1">4. 个性化首页与频道自定义 <a class="header-anchor" href="#_4-个性化首页与频道自定义" aria-label="Permalink to &quot;4. 个性化首页与频道自定义&quot;">​</a></h2><ul><li><strong>自定义频道</strong>：在个人首页点击“配置频道”，可自由新增自定义规则分组（如 <code>我的ACG精选</code>、<code>80年代怀旧</code>）。</li><li><strong>拖拽排序与显隐</strong>：拖拽调整首页展示频道的排列顺序，一键隐藏或恢复系统预设频道。</li></ul><hr><h2 id="_5-参与社区共建" tabindex="-1">5. 参与社区共建 <a class="header-anchor" href="#_5-参与社区共建" aria-label="Permalink to &quot;5. 参与社区共建&quot;">​</a></h2><ul><li><strong>创建新词条</strong>：若未搜到心仪作品，点击顶部导航的 <strong>“录入中心”</strong>，基于向导录入作品与发行版信息。</li><li><strong>修正现有词条</strong>：在任意详情页点击 <strong>“编辑”</strong> 按钮，补充缺失的制作人员、外部 ID 或关联关系。</li><li><strong>社区交流</strong>：访问社区论坛，与同好交流文献考据心得，讨论作品背景与版本差异。</li></ul><hr><h2 id="_6-开发者接入" tabindex="-1">6. 开发者接入 <a class="header-anchor" href="#_6-开发者接入" aria-label="Permalink to &quot;6. 开发者接入&quot;">​</a></h2><p>如果你希望开发第三方客户端、自动化同步脚本或 AI Agent：</p><ul><li>前往 <strong>设置 (Settings) → 开发者</strong> 页面生成个人访问令牌 (PAT)；</li><li>阅读 <a href="/docs/api-overview">开放 API 架构概览</a> 与接口文档，即可直接调用平台全部 REST 接口。</li></ul>',22)])])}const _=a(l,[["render",e]]);export{g as __pageData,_ as default};
